const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Audit log configuration
const AUDIT_LOG_PATH = path.join(__dirname, 'audit.log');
const MAX_LOG_SIZE = 10 * 1024 * 1024;

// Solidity contract validation patterns
const PATTERNS = {
  // Validates Solidity function signatures like "transfer(address,uint256)"
  functionSig: /^[a-zA-Z_][a-zA-Z0-9_]*\(([a-zA-Z0-9_\[\]]*,?)*\)$/,
  // Validates contract addresses
  address: /^0x[0-9a-fA-F]{40}$/,
  // Validates transaction hashes
  txHash: /^0x[0-9a-fA-F]{64}$/,
  // Validates Solidity type declarations for ABI encoding
  solidityType: /^(uint|int|address|bool|bytes|string|tuple)(\d{0,3})(\[\d*\])*$/,
  // Validates event signatures with indexed params
  eventSig: /^[a-zA-Z_][a-zA-Z0-9_]*\(((indexed\s+)?[a-zA-Z0-9_\[\]]+,?)*\)$/
};

function writeAuditLog(entry) {
  const timestamp = new Date().toISOString();
  const logEntry = JSON.stringify({ timestamp, ...entry }) + '\n';
  try {
    const stats = fs.statSync(AUDIT_LOG_PATH).size;
    if (stats > MAX_LOG_SIZE) {
      fs.truncateSync(AUDIT_LOG_PATH, 0);
    }
  } catch (e) {
    // File doesn't exist yet, will be created
  }
  fs.appendFileSync(AUDIT_LOG_PATH, logEntry);
}

function generateRequestId() {
  return crypto.randomBytes(16).toString('hex');
}

function validateContractInput(input, type) {
  if (!PATTERNS[type]) {
    return { valid: false, error: `Unknown validation type: ${type}` };
  }
  const result = PATTERNS[type].test(input);
  return { valid: result, error: result ? null : `Invalid ${type} format` };
}

function parseABIParameters(paramString) {
  // Split parameters and validate each one
  const params = paramString.split(',').filter(p => p.trim().length > 0);
  const validated = [];
  for (const param of params) {
    const trimmed = param.trim();
    const typeCheck = validateContractInput(trimmed, 'solidityType');
    if (!typeCheck.valid) {
      return { success: false, error: `Invalid parameter type: ${trimmed}` };
    }
    validated.push(trimmed);
  }
  return { success: true, params: validated };
}

// Middleware: request tracking
app.use((req, res, next) => {
  req.requestId = generateRequestId();
  req.startTime = Date.now();
  next();
});

// POST /api/v1/contract/validate-signature
app.post('/api/v1/contract/validate-signature', (req, res) => {
  const { signature, contractAddress } = req.body;

  if (!signature || !contractAddress) {
    writeAuditLog({
      requestId: req.requestId,
      action: 'validate-signature',
      status: 'error',
      reason: 'missing_fields'
    });
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate contract address first
  const addrCheck = validateContractInput(contractAddress, 'address');
  if (!addrCheck.valid) {
    writeAuditLog({
      requestId: req.requestId,
      action: 'validate-signature',
      status: 'rejected',
      reason: 'invalid_address',
      input: contractAddress.substring(0, 42)
    });
    return res.status(400).json({ error: addrCheck.error });
  }

  // Validate function signature format
  const sigCheck = validateContractInput(signature, 'functionSig');

  writeAuditLog({
    requestId: req.requestId,
    action: 'validate-signature',
    status: sigCheck.valid ? 'success' : 'rejected',
    contractAddress,
    signatureValid: sigCheck.valid
  });

  if (!sigCheck.valid) {
    return res.status(400).json({ error: sigCheck.error });
  }

  // Extract function name and compute selector
  const funcName = signature.split('(')[0];
  const selector = crypto.createHash('sha3-256')
    .update(signature)
    .digest('hex')
    .substring(0, 8);

  return res.json({
    requestId: req.requestId,
    valid: true,
    functionName: funcName,
    selector: '0x' + selector,
    contractAddress
  });
});

// POST /api/v1/contract/decode-event
app.post('/api/v1/contract/decode-event', (req, res) => {
  const { eventSignature, txHash, topics } = req.body;

  if (!eventSignature || !txHash) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const txCheck = validateContractInput(txHash, 'txHash');
  if (!txCheck.valid) {
    writeAuditLog({
      requestId: req.requestId,
      action: 'decode-event',
      status: 'rejected',
      reason: 'invalid_txhash'
    });
    return res.status(400).json({ error: txCheck.error });
  }

  // Validate event signature - this uses the eventSig pattern
  const eventCheck = validateContractInput(eventSignature, 'eventSig');

  writeAuditLog({
    requestId: req.requestId,
    action: 'decode-event',
    status: eventCheck.valid ? 'success' : 'rejected',
    txHash
  });

  if (!eventCheck.valid) {
    return res.status(400).json({ error: eventCheck.error });
  }

  return res.json({
    requestId: req.requestId,
    decoded: true,
    eventSignature,
    txHash,
    topicCount: topics ? topics.length : 0
  });
});

// POST /api/v1/contract/encode-abi
app.post('/api/v1/contract/encode-abi', (req, res) => {
  const { functionName, parameters } = req.body;

  if (!functionName || !parameters) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const nameCheck = /^[a-zA-Z_][a-zA-Z0-9_]{0,63}$/.test(functionName);
  if (!nameCheck) {
    return res.status(400).json({ error: 'Invalid function name' });
  }

  const paramResult = parseABIParameters(parameters);
  if (!paramResult.success) {
    writeAuditLog({
      requestId: req.requestId,
      action: 'encode-abi',
      status: 'rejected',
      reason: paramResult.error
    });
    return res.status(400).json({ error: paramResult.error });
  }

  const fullSig = `${functionName}(${paramResult.params.join(',')})`;
  const selector = crypto.createHash('sha3-256')
    .update(fullSig)
    .digest('hex')
    .substring(0, 8);

  writeAuditLog({
    requestId: req.requestId,
    action: 'encode-abi',
    status: 'success',
    signature: fullSig
  });

  return res.json({
    requestId: req.requestId,
    selector: '0x' + selector,
    signature: fullSig,
    parameterCount: paramResult.params.length
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Solidity API server running on port ${PORT}`);
});

module.exports = app;
